#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    if (N == 2) {
        cout << -1 << '\n';
        return 0;
    }

    vector<int> d = {0};
    int m = N - 1;

    if (m % 2 == 0) {
        for (int k = 1; k <= m / 2; ++k) {
            d.push_back(k);
            d.push_back(-k);
        }
    } else if (m >= 3) {
        d.push_back(1);
        d.push_back(2);
        d.push_back(-3);
        for (int k = 4; (int)d.size() + 2 <= N; ++k) {
            d.push_back(k);
            d.push_back(-k);
        }
    }

    int M = 0;
    for (int x : d) M = max(M, abs(x));

    int K = 2 * M + 1;
    int base = (K + 1) * M + 1;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (j) cout << ' ';
            cout << base + K * d[i] + d[j];
        }
        cout << '\n';
    }

    return 0;
}
